-- ============================================================
-- Comuni geodata reference + geocode backfill for clubs / club_teams
--
-- Enables geographic discovery for "Cerca -> Posizioni aperte":
--   * province filtering (clubs/club_teams had region + city only)
--   * distance / radius ("Vicino a me") via denormalized coordinates
--
-- Source data (joined on ISTAT code, regenerate via
-- supabase/scripts/comuni/generate.js):
--   * matteocontrini/comuni-json  -> name, ISTAT codice, provincia, sigla, regione
--   * MatteoHenryChinaski/Comuni-Italiani-2018 italy_geo.json -> lat/lng by ISTAT
-- Province labels normalized to the app's PROVINCE_OPTIONS canonical form
-- (Bolzano/Bozen -> Bolzano, Monza e della Brianza -> Monza e Brianza,
--  Reggio nell'Emilia -> Reggio Emilia, Valle d'Aosta/... -> Aosta).
-- 7904 comuni, 7859 with coordinates (45 post-2018 fusion comuni: null coords).
-- ============================================================

-- Normalization mirrors normalizeLookupValue() in
-- apps/mobile/src/features/profiles/profile-form-utils.ts:
--   trim -> NFD -> strip combining marks -> lower -> non-alnum to space -> trim
create or replace function public.footme_normalize_lookup(p text)
returns text
language sql
immutable
as $$
  select trim(regexp_replace(
    lower(regexp_replace(
      normalize(coalesce(p, ''), NFD),
      '[' || U&'\0300' || '-' || U&'\036F' || ']', '', 'g'
    )),
    '[^a-z0-9]+', ' ', 'g'
  ));
$$;

-- Reference table of Italian comuni with province + coordinates.
create table if not exists public.italian_comuni (
  name          text not null,
  name_norm     text not null,
  province      text not null,
  province_code text not null,
  region        text not null,
  latitude      double precision,
  longitude     double precision
);

create index if not exists italian_comuni_name_norm_idx
  on public.italian_comuni (name_norm);

alter table public.italian_comuni enable row level security;

drop policy if exists "italian_comuni_read" on public.italian_comuni;
create policy "italian_comuni_read"
  on public.italian_comuni
  for select
  to authenticated
  using (true);

-- Idempotent reseed.
truncate table public.italian_comuni;

