-- Denormalized geo columns on clubs / club_teams (both already have city + region).
alter table public.clubs add column if not exists province text;
alter table public.clubs add column if not exists latitude double precision;
alter table public.clubs add column if not exists longitude double precision;

alter table public.club_teams add column if not exists province text;
alter table public.club_teams add column if not exists latitude double precision;
alter table public.club_teams add column if not exists longitude double precision;

-- Backfill: match normalized city; prefer the comune in the row's own region
-- to disambiguate identically-named comuni across provinces.
with matches as (
  select distinct on (c.id)
    c.id, ic.province, ic.latitude, ic.longitude
  from public.clubs c
  join public.italian_comuni ic
    on ic.name_norm = public.footme_normalize_lookup(c.city)
   and ic.latitude is not null
  where c.city is not null and c.city <> ''
  order by c.id, (ic.region is not distinct from c.region) desc
)
update public.clubs c
set province = m.province, latitude = m.latitude, longitude = m.longitude
from matches m
where m.id = c.id;

with matches as (
  select distinct on (t.id)
    t.id, ic.province, ic.latitude, ic.longitude
  from public.club_teams t
  join public.italian_comuni ic
    on ic.name_norm = public.footme_normalize_lookup(t.city)
   and ic.latitude is not null
  where t.city is not null and t.city <> ''
  order by t.id, (ic.region is not distinct from t.region) desc
)
update public.club_teams t
set province = m.province, latitude = m.latitude, longitude = m.longitude
from matches m
where m.id = t.id;

-- Keep geo fresh when city/region change (security definer to read reference under RLS).
create or replace function public.footme_geocode_location()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.city is null or new.city = '' then
    new.province := null;
    new.latitude := null;
    new.longitude := null;
    return new;
  end if;

  select ic.province, ic.latitude, ic.longitude
    into new.province, new.latitude, new.longitude
  from public.italian_comuni ic
  where ic.name_norm = public.footme_normalize_lookup(new.city)
    and ic.latitude is not null
  order by (ic.region is not distinct from new.region) desc
  limit 1;

  return new;
end;
$$;

drop trigger if exists clubs_geocode on public.clubs;
create trigger clubs_geocode
  before insert or update of city, region on public.clubs
  for each row execute function public.footme_geocode_location();

drop trigger if exists club_teams_geocode on public.club_teams;
create trigger club_teams_geocode
  before insert or update of city, region on public.club_teams
  for each row execute function public.footme_geocode_location();
